const cfg={
versiya_workflow:'client-core-wf02b2a-0.1',
versiya_prompta:'pre02e-pending',
kanal:'telegram',
akkaunt_kanala_id:'ЗАПОЛНИТЬ_ID_КЛИЕНТСКОГО_TELEGRAM_БОТА',
sluzhebnyy_chat_id:'ЗАПОЛНИТЬ_ID_СЛУЖЕБНОЙ_FORUM_ГРУППЫ',
nachalnyy_etap:'pervichnyy_kontakt',prioritet:0};
const ready=!cfg.akkaunt_kanala_id.startsWith('ЗАПОЛНИТЬ')&&!cfg.sluzhebnyy_chat_id.startsWith('ЗАПОЛНИТЬ');
return $input.all().map(i=>({json:{...i.json,_nastroyki_vhoda:cfg,profil_vhoda_gotov:ready},binary:i.binary}));

const root=$json||{},cfg=root._nastroyki_vhoda,body=root.body||{};
const m=body.message||body.edited_message||null,cb=body.callback_query||null;
const updateId=body.update_id;if(updateId===undefined||updateId===null)throw new Error('Нет Telegram update_id');
let chatId=null,fromId=null,messageId=null,sourceDate=null,eventType='message',messageType='system',text='',fileId=null,callbackData=null;
if(m){chatId=m.chat?.id??null;fromId=m.from?.id??null;messageId=m.message_id??null;sourceDate=m.date?new Date(Number(m.date)*1000).toISOString():null;
if(typeof m.text==='string'){messageType='text';text=m.text;}else if(m.voice){messageType='voice';fileId=m.voice.file_id??null;}else if(m.photo){messageType='photo';fileId=m.photo.at(-1)?.file_id??null;text=m.caption||'';}else if(m.video){messageType='video';fileId=m.video.file_id??null;text=m.caption||'';}else if(m.document){messageType='document';fileId=m.document.file_id??null;text=m.caption||'';}else if(m.sticker){messageType='sticker';fileId=m.sticker.file_id??null;}}
else if(cb){eventType='callback';callbackData=String(cb.data||'');chatId=cb.message?.chat?.id??null;fromId=cb.from?.id??null;messageId=cb.message?.message_id??null;sourceDate=cb.message?.date?new Date(Number(cb.message.date)*1000).toISOString():null;if(callbackData==='media_take'){messageType='text';text='Позвать менеджера';}else if(callbackData==='media_no'){messageType='text';text='Продолжить без менеджера';}}
if(chatId===null||fromId===null)throw new Error('Не удалось определить chat_id/from_id');
const fp=['fp1',String(updateId),String(chatId),String(fromId),String(messageId??''),eventType,messageType,text,String(fileId??''),String(callbackData??'')].join('|');
const ingress={versiya_formata:1,operaciya_id:'tg_client_ingress:'+cfg.akkaunt_kanala_id+':'+updateId,klyuch_idempotentnosti:'telegram:'+cfg.akkaunt_kanala_id+':update:'+updateId,hash_soderzhaniya:fp,kanal:cfg.kanal,akkaunt_kanala_id:cfg.akkaunt_kanala_id,vneshnee_sobytie_id:String(updateId),vneshniy_polzovatel_id:String(fromId),vneshniy_dialog_id:String(chatId),vneshnee_soobshchenie_id:messageId===null?null:String(messageId),tip_sobytiya:eventType,tip_soobshcheniya:messageType,tekst_ishodnyy:text,vremya_istochnika:sourceDate,vremya_priema:new Date().toISOString(),trassirovka_id:'telegram:'+updateId,versiya_workflow:cfg.versiya_workflow,versiya_prompta:cfg.versiya_prompta,payload_ishodnyy:body,sluzhebnyy_chat_id:cfg.sluzhebnyy_chat_id,bezopasnaya_podpis_klienta:'Клиент •••'+String(fromId).slice(-4),nachalnyy_etap:cfg.nachalnyy_etap,prioritet:cfg.prioritet};
return [{json:{db_ingress:ingress}}];

const j=$json;
const job={zadanie_id:j.zadanie_id,dialog_id:j.dialog_id,worker_id:j.vladelec_arendy,nomer_vladeniya:j.nomer_vladeniya,versiya_dialoga:j.versiya_dialoga,arenda_do:j.arenda_do,popytki:j.popytki};
return [{json:{job,db_source:{operaciya_id:'source:'+j.zadanie_id+':'+j.nomer_vladeniya,zadanie_id:j.zadanie_id,worker_id:j.vladelec_arendy,nomer_vladeniya:j.nomer_vladeniya,ozhidaemaya_versiya_dialoga:j.versiya_dialoga}}}];

const x=$json;
const source={identifikator_kanala_id:x.identifikator_kanala_id,soobshchenie_id:x.soobshchenie_id,tip_soobshcheniya:x.tip_soobshcheniya,tekst_ishodnyy:x.tekst_ishodnyy,kanal:x.kanal,akkaunt_kanala_id:x.akkaunt_kanala_id,vneshniy_dialog_id:x.vneshniy_dialog_id};
return [{json:{job:x.job,source,db_context:{operaciya_id:'context:'+x.job.zadanie_id+':'+x.job.nomer_vladeniya,dialog_id:x.job.dialog_id,zadanie_id:x.job.zadanie_id,ozhidaemaya_versiya_dialoga:x.job.versiya_dialoga}}}];

const x=$json;
let t=String(x.source?.tekst_ishodnyy??'');
const known=Array.isArray(x.lokalnye_pii?.sootvetstviya)?x.lokalnye_pii.sootvetstviya:[];
const used=new Set(known.map(z=>String(z.psevdometka||'')));
const maps=[];
function esc(s){return String(s).replace(/[-/\^$*+?.()|[\]{}]/g,'\\$&')}
for(const z of known){const v=z?.znachenie_zashchishchennoe,p=z?.psevdometka;if(v&&p)t=t.replace(new RegExp(esc(v),'gi'),p)}
function next(prefix,tip,val,extra={}){let n=1,p;do{p=prefix+'_'+String(n++).padStart(2,'0')}while(used.has(p));used.add(p);maps.push({tip_pii:tip,psevdometka:p,znachenie_zashchishchennoe:String(val),...extra});return p}
t=t.replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,m=>next('EMAIL','email',m));
t=t.replace(/(?<!\w)(?:\+?\d[\d\s().-]{8,}\d)(?!\w)/g,m=>next('PHONE','telefon',m,{region_telefona:'RU'}));
t=t.replace(/(?<!\w)@[A-Za-z0-9_]{5,32}\b/g,m=>next('USERNAME','telegram_username',m));
t=t.replace(/\b(меня\s+зовут|мо[её]\s+имя)\s+([А-ЯЁA-Z][А-ЯЁA-Za-zа-яё-]{1,40})/gi,(m,p,n)=>p+' '+next('PERSON','imya',n));
const safe=t.trim();
return [{json:{job:x.job,source:x.source,ai_kontekst:x.ai_kontekst,tekst_bez_pii:safe,db_pii:{
 operaciya_id:'pii:'+x.source.soobshchenie_id,
 soobshchenie_id:x.source.soobshchenie_id,
 tekst_obezlichennyy:safe,
 sootvetstviya:maps,
 region_telefona:'RU'
}}}];

const x=$json;
const voice=x.payload_ishodnyy?.message?.voice||x.payload_ishodnyy?.edited_message?.voice||{};
const fileId=voice.file_id||null;
const fileSize=Number(voice.file_size||0);
const duration=Number(voice.duration||0);
const runtime={
  job:x.job,
  source:{
    identifikator_kanala_id:x.identifikator_kanala_id,
    soobshchenie_id:x.soobshchenie_id,
    tip_soobshcheniya:x.tip_soobshcheniya,
    tekst_ishodnyy:'',
    kanal:x.kanal,
    akkaunt_kanala_id:x.akkaunt_kanala_id,
    vneshniy_dialog_id:x.vneshniy_dialog_id
  },
  file_id:fileId,file_size:fileSize,duration,
  stt_url:'http://stt-local:8000/v1/transcriptions',
  stt_runtime_verified:false,
  stt_limits_ok:Boolean(fileId)&&(!fileSize||fileSize<=20*1024*1024)&&(!duration||duration<=300)
};
return [{json:{runtime}}];

const x=$json,r=x.runtime;
const t=String(x.text??x.transcript??x.result?.text??'').trim();
const err=x.error?.message||x.message||'local_stt_no_text';
return [{json:{runtime:r,stt_ok:Boolean(t),stt_text:t,stt_error:Boolean(t)?null:String(err)}}];

const x=$json,r=x.runtime;
r.source.tekst_ishodnyy=x.stt_text;
return [{json:{runtime:r,db_stt:{operaciya_id:'stt:done:'+r.source.soobshchenie_id,status:'gotova',soobshchenie_id:r.source.soobshchenie_id,tekst_transkripcii:x.stt_text,tekst_obezlichennyy:null,dvizhok:'local-stt-http',versiya_dvizhka:'route-verified-at-runtime',popytki:Number(r.job.popytki||1),vremya_zaversheniya:new Date().toISOString()}}}];
